function refreshFaces(){if(!renderer)return;for(const face of faceMeshes){textures=textures.filter(t=>t!==face.material.map);face.material.map.dispose();face.material.map=faceTexture(face.userData.layer);face.material.needsUpdate=true;}for(const m of padMeshes)m.material.color.set(functionalPadColor(m.userData.pad)||notebook.data.nets[m.userData.pad.net]||(m.userData.pad.net===state.net?'#ffffff':'#d1a14a'));refreshInstanceColors();refreshTraceOverlay();}
function updateProbeGeometry(){if(!probeGroup)return;while(probeGroup.children.length){let c=probeGroup.children[0];probeGroup.remove(c);c.geometry?.dispose();}for(const [which,col]of [['black','#272d30'],['red','#cf393a']]){const p=board.pads.find(p=>p.id===state[which]);if(!p)continue;const side=viewBottom?-1:1,z=side<0?-1.35:.13;const tip=[p.x,p.y,z],mid=[p.x+.1,p.y+.5,z+side*2.5],end=[p.x+1.5,p.y+1.2,z+side*6.4];cylinder(tip,mid,.13,materials.silver,probeGroup);cylinder(mid,end,.44,mat(col,.33,.15),probeGroup);const ring=cylinder([p.x,p.y,z],[p.x,p.y,z+side*.04],.8,new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:.7,side:THREE.DoubleSide}),probeGroup);}}
function init3D(){scene=new THREE.Scene();scene.background=new THREE.Color('#d5dee3');camera=new THREE.PerspectiveCamera(38,1,.1,1000);camera.up.set(0,0,1);renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.NeutralToneMapping;renderer.toneMappingExposure=1.0;$('stage').append(renderer.domElement);const pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(new RoomEnvironment(),.04).texture;pmrem.dispose();scene.environmentIntensity=.25;scene.add(new THREE.HemisphereLight('#ffffff','#263d32',.6));const key=new THREE.DirectionalLight('#ffffff',2.0);key.position.set(-60,-85,160);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.bias=-.0003;key.shadow.normalBias=.045;key.name='studioKey';scene.add(key);const fill=new THREE.DirectionalLight('#ffffff',1.0);fill.position.set(10,20,-20);scene.add(fill);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=8;controls.maxDistance=500;controls.target.set(0,0,1);controls.enablePan=true;controls.addEventListener('change',()=>{const changed=viewBottom!==(camera.position.z<0);viewBottom=camera.position.z<0;if(changed&&board)updateProbeGeometry();$('faceName').textContent=layerChoice==='surface'?(viewBottom?'Cara de soldaduras · inferior':'Cara de componentes · superior'):layerLabel(Number(layerChoice));});const resize=()=>{const w=$('stage').clientWidth,h=$('stage').clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();if(board)homeView();};new ResizeObserver(resize).observe($('stage'));resize();let start=null;renderer.domElement.addEventListener('pointerdown',e=>start={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)<7)pick(e);start=null;});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('loading').style.display='grid';$('loading').textContent='Se ha pausado el motor 3D. Recarga la página para recuperarlo.'});function frame(){requestAnimationFrame(frame);if($('labPage').hidden)return;controls.update();renderer.render(scene,camera);}frame();$('loading').style.display='none';}
function homeView(){if(!camera||!controls||!board)return;fitBoard(THREE,camera,controls,board.bounds);viewBottom=false;updateProbeGeometry();}
function flip(){if(!camera||!controls)return;let p=camera.position.clone();p.z=-p.z;if(Math.abs(p.z)<6)p.z=viewBottom?25:-25;camera.position.copy(p);controls.update();viewBottom=p.z<0;updateProbeGeometry();}
function pick(event){const rect=renderer.domElement.getBoundingClientRect();const m=new THREE.Vector2((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1),ray=new THREE.Raycaster();ray.params.Line.threshold=Math.max(.09,Math.min(.5,camera.position.distanceTo(controls.target)*.002));ray.setFromCamera(m,camera);const hits=ray.intersectObjects([...faceMeshes.filter(o=>o.visible),...pickables.filter(o=>isPickable(o))]);if(!hits.length)return;const hit=hits[0],h=hit.object;if(h.userData.padEntries){const p=h.userData.padEntries[hit.instanceId];if(p?.id)selectPad(p.id);else if(p?.net)onNetClick(p.net);return;}if(h.userData.pad){selectPad(h.userData.pad.id);return;}if(h.userData.net){const seg=h.userData.segment||(h.userData.segmentIds&&h.userData.segmentIds[Math.floor(hit.index/2)]);if(interaction==='segment'&&seg){notebook.markSegment(seg,markColor);notesChanged();}else onNetClick(h.userData.net);return;}const component=h.userData.component||(h.userData.componentEntries&&h.userData.componentEntries[hit.instanceId]);if(component){const el=component;if(board.blocks){$('blockComponent').value=el.name;focusBlockComponent(el.name);}inspectPart(el.name);if(el.pads.length===2){selectNet(board.pads.find(p=>p.id===el.pads[0]).net);}}}
function selectPad(id){if(interaction==='point'){notebook.point(id,$('pointNote').value.trim());$('pointNote').value='';selectNet(board.pads.find(p=>p.id===id).net);notesChanged();return;}if(interaction==='net'){onNetClick(board.pads.find(p=>p.id===id).net);return;}if(interaction==='inspect'||interaction==='segment'){selectNet(board.pads.find(p=>p.id===id).net);$('padLabel').textContent=id+' · '+board.pads.find(p=>p.id===id).net;$('padLabel').style.display='block';return;}state[state.probe]=id;const p=board.pads.find(p=>p.id===id);selectNet(p.net);$('padLabel').textContent=`${p.id} · ${p.net} → punta ${state.probe==='red'?'roja':'negra'}`;$('padLabel').style.display='block';updateProbeGeometry();updateUI();}
function selectNet(net){state.net=net;refreshFaces();renderNet();renderSchema();$('isolateNet').disabled=!net;}
function renderNet(){document.querySelectorAll('#nets button').forEach(b=>b.classList.toggle('active',b.dataset.net===state.net));$('netName').textContent=state.net||'—';const n=board.nets.find(n=>n.name===state.net);const explain=board.id==='mosfet'?{GND:'Retorno común. Conecta la fuente de Q1 (pin 3) con las masas de los conectores.',VCC:'Alimentación positiva. Se entrega a la carga externa; no atraviesa la puerta del MOSFET.',CONTROL:'Mando de puerta. R1 de 10 kΩ lo mantiene bajo si el control externo se desconecta.','HIGH-CURRENT':'Nodo del drenador de Q1. La carga externa se conecta entre VCC y este nodo.'}:{GND:'Referencia común de los dominios de 3,3 V y 5 V.',LV:'Alimentación baja, 3,3 V en el ejercicio. Polariza las puertas y los pull-up del lado LV.',HV:'Alimentación alta, 5 V en el ejercicio. Alimenta los pull-up del lado HV.'};$('netExplain').textContent=n?(((board.educational?({VIN:'Entrada de alimentación del circuito.',OUT:'Salida entre componentes: relaciona su tensión con el funcionamiento.',GND:'Referencia y retorno de la fuente.'}[state.net]):board.exploreOnly?'Red del diseño real. Consulta los contactos y los bloques que relaciona.':explain[state.net])||`Señal del canal ${state.net.replace(/\D/g,'')}, lado ${state.net.startsWith('LV')?'3,3':'5'} V. Sigue su resistencia pull-up y su transistor.`)+` ${n.contacts.length} contactos · ${n.wires.length} tramos · ${n.vias.length} vías.`+(n.polygons.length?' Incluye un plano de cobre: se muestra su contorno punteado.':'')):'Toca una pista o un pad para descubrir qué conecta.';$('netMembers').replaceChildren();for(const id of n?.contacts||[]){let b=document.createElement('button');b.textContent=id;b.title='Colocar la punta activa en '+id;b.onclick=()=>selectPad(id);$('netMembers').append(b);}}
