 if(board.exploreOnly){$('conditions').textContent=board.representative?'Conexiones de entrenamiento. No hay simulación de tensiones o resistencias; los pads de este modelo no representan un pinout comercial.':'Conectividad del diseño CAD: solo redes. Sin simulación eléctrica de esta placa compleja.';}else if(board.educational){$('conditions').textContent=board.kind==='rc'?'R1 = 10 kΩ · C1 = 100 nF · τ = 1 ms. Carga desde 0 V; fuente ideal y salida sin carga. El cursor representa una carga tras un escalón.':board.kind==='divider'?'R1 = R2 = 10 kΩ. Divisor ideal, sin carga externa.':'R1 = 1 kΩ · LED rojo: caída constante ideal de 2 V. Corriente nominal: 3 mA a 5 V.';}else if(board.id==='mosfet'){$('conditions').textContent='Carga externa: 100 Ω entre VCC y drenador. Modelo: RDS(on) = 0,047 Ω a mando alto; gate sin corriente DC. Al apagar la fuente se retiran fuente y carga para Ω.';}else{$('conditions').textContent='LV = 3,3 V · HV = 5 V. El mando afecta solo al canal 1. Bajo: ambos lados ≈ 0 V; liberado: cada pull-up fija su nivel. Modelo digital ideal.';}
