function options(){$('power').disabled=!!board.exploreOnly;$('drive').disabled=!!board.exploreOnly;for(const id of ['blackPad','redPad']){const sel=$(id);sel.innerHTML='<option value="">Sin conectar</option>';for(const p of board.pads.filter(p=>p.net)){const o=document.createElement('option');o.value=p.id;o.textContent=`${p.id} · ${p.net}`;sel.append(o);}}$('nets').replaceChildren();for(const n of board.nets){let b=document.createElement('button');b.textContent=shortNet(n.name);b.title=n.name;b.dataset.net=n.name;b.onclick=()=>onNetClick(n.name);$('nets').append(b);}if(board.exploreOnly){blockOptions();return;}if(board.educational){practiceOptions();return;}$('fault').innerHTML='<option value="none">Circuito correcto</option><option value="rOpen">R1 abierta</option><option value="qShort">Q1: drenador-fuente en corto</option>';const label=$('controlLabel');label.firstChild.textContent=board.id==='mosfet'?'Mando CONTROL':'Canal 1 · entrada de colector/drenador abierto';$('drive').options[0].textContent=board.id==='mosfet'?'Bajo · 0 V':'Forzar bajo · ambos lados 0 V';$('drive').options[1].textContent=board.id==='mosfet'?'Alto · 5 V':'Liberado · LV1 3,3 V / HV1 5 V';$('fault').disabled=board.id==='logic'||activeMission===6;$('fault').hidden=activeMission===6;$('faultExplain').textContent=activeMission===6?'Avería oculta del reto. Investiga con las medidas antes de elegir tu diagnóstico.':board.id==='logic'?'En esta placa se practican redes y niveles lógicos. Las averías se entrenan en el controlador MOSFET.':'Elige una avería del controlador y compara su respuesta con el circuito correcto.';$('sourceText').innerHTML=`<p><b>${board.title}</b> · SparkFun Electronics<br><a href="${board.source}" target="_blank" rel="noopener">Archivos originales y licencia ↗</a> · <a href="https://creativecommons.org/licenses/by-sa/${board.id==='logic'?'3.0':'4.0'}/" target="_blank" rel="noopener">${board.license}</a></p><p>Diseño derivado, convertido a un modelo educativo interactivo. Revisión importada: ${board.commit.slice(0,12)}. El modelo no está fabricado ni validado por SparkFun.</p>`;}
function setBoard(id){wsBlockMode='off';applyWorkstationBlocks();board=boards.find(b=>b.id===id);notebook.load(id);$('componentInfo').replaceChildren();if(rcTimer){clearInterval(rcTimer);rcTimer=null;}$('animateRC').textContent='▶ Ver la carga';state.time=5;$('timeSlider').value=5;$('timeValue').textContent='5,00 ms';$('timeControl').hidden=board.kind!=='rc';$('realBadge').textContent=board.representative?'ARQUITECTURA DIDÁCTICA':board.educational?'CIRCUITO DIDÁCTICO':'CAD REAL';state.red='';state.black='';state.net='';state.fault=activeMission===6?'qShort':'none';state.power=false;state.drive='low';layerChoice='surface';$('boardSelect').value=id;options();if(renderer)buildBoard();renderNet();renderSchema();updateUI();renderNotes();setupBlocks();setupProGuide();renderSchema();workstation?.refresh();}
function renderMissions(){$('missions').replaceChildren();for(let i=0;i<missions.length;i++){const search=($('exerciseSearch')?.value||'').toLowerCase();const group=$('exerciseGroup')?.value||'all';if(group!=='all'&&missions[i].board!==group||!(missions[i].title+' '+missions[i].text).toLowerCase().includes(search))continue;let b=document.createElement('button');b.className='mission'+(i===activeMission?' active':'')+(done.has(i)?' done':'');b.innerHTML=`<span class="num">${done.has(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${missions[i].title}</span>`;b.onclick=()=>startMission(i);$('missions').append(b);}$('progressText').textContent=`${done.size} de ${missions.length} retos completados`;$('progressFill').style.width=(done.size/missions.length*100)+'%';}
function startMission(i){document.dispatchEvent(new CustomEvent('circuitlab:workspace',{detail:'diagnose'}));activeMission=i;setTool('inspect');seenOnDrain=false;$('feedback').textContent='';$('hint').hidden=true;$('componentInfo').textContent='';$('padLabel').style.display='none';const m=missions[i];$('lessonTag').textContent=m.tag;$('lessonTitle').textContent=m.title;$('lessonText').textContent=m.text;$('hint').textContent=m.hint;$('check').hidden=false;$('hintBtn').hidden=false;$('free').classList.remove('active');$('diagnosis')?.remove();if(i===6){let s=document.createElement('select');s.id='diagnosis';s.style.cssText='width:100%;margin:8px 0;padding:9px;border-radius:8px;border:1px solid #d8e1d4';s.innerHTML='<option value="">Mi diagnóstico…</option><option value="r">R1 abierta</option><option value="short">Q1 en corto entre D y S</option><option value="normal">Es el comportamiento normal</option>';$('check').before(s);}state.mode='voltage';state.probe='red';renderMissions();setBoard(m.board);}
function freeMode(){document.dispatchEvent(new CustomEvent('circuitlab:workspace',{detail:'inspect'}));activeMission=-1;$('diagnosis')?.remove();$('lessonTag').textContent='EXPLORACIÓN LIBRE';$('lessonTitle').textContent='Tu banco, tus preguntas.';$('lessonText').textContent='Elige una placa, sigue una red y prueba tus predicciones. Las listas de pads te permiten medir también cuando un componente oculta una conexión.';$('hint').hidden=true;$('hintBtn').hidden=true;$('check').hidden=true;$('feedback').textContent='';$('free').classList.add('active');state.fault='none';options();renderMissions();updateUI();}
