function paintBlocks(focus=''){if(!parts||!board.blocks)return;refreshInstanceColors();parts.traverse(o=>{if(o.userData.componentEntries){for(let i=0;i<o.count;i++){const el=o.userData.componentEntries[i],b=board.blocks.find(b=>b.elements.includes(el.name));o.setColorAt(i,new THREE.Color(el.name===focus?'#ffffff':showBlockSolution&&b?b.color:o.userData.baseColor));}o.instanceColor.needsUpdate=true;return;}if(!o.isMesh||!o.userData.component)return;if(!o.userData.blockMaterial){o.material=o.material.clone();o.userData.blockMaterial=true;}const ref=o.userData.component.name,b=board.blocks.find(b=>b.elements.includes(ref));o.material.emissive?.set(ref===focus?'#ffffff':showBlockSolution&&b?b.color:'#000000');o.material.emissiveIntensity=ref===focus?.5:showBlockSolution&&b?.75:0;});for(const m of padMeshes){const ref=m.userData.pad.element||m.userData.pad.id.split('.')[0],b=board.blocks.find(b=>b.elements.includes(ref));m.material.color.set(showBlockSolution&&b?b.color:notebook.data.nets[m.userData.pad.net]||(m.userData.pad.net===state.net?'#ffe695':'#d1a14a'));}tintComponentFamilies(parts,familyColors,THREE);if(wsBlockMode!=='off')applyWorkstationBlocks();}
