function buildInstancedPads(){const sets=new Map();const add=(key,geo,p,z,scale)=>{if(!sets.has(key))sets.set(key,{geo,list:[]});else geo?.dispose();sets.get(key).list.push({p,z,scale});};for(const p of board.pads){for(const z of p.drill?[.065,-1.32]:[p.layer===16?-1.32:.065]){if(p.drill){const ratio=Math.round(p.drill/p.diameter*20)/20;add('ring'+ratio,new THREE.RingGeometry(ratio,.99,16),p,z,[p.diameter/2,p.diameter/2]);}else add('plane',new THREE.PlaneGeometry(1,1),p,z,[p.dx,p.dy]);}}
 for(const n of board.nets)for(const v of n.vias)for(const z of [.07,-1.33]){const p={...v,net:n.name,id:null},d=v.diameter||v.drill*2,ratio=Math.round(v.drill/d*20)/20;add('ring'+ratio,new THREE.RingGeometry(ratio,.99,16),p,z,[d/2,d/2]);}
 for(const {geo,list}of sets.values()){const material=mat('#d1a14a',.35,.72);material.side=THREE.DoubleSide;const m=new THREE.InstancedMesh(geo,material,list.length),dummy=new THREE.Object3D();m.userData.padEntries=list.map(x=>x.p);for(let i=0;i<list.length;i++){const {p,z,scale}=list[i];dummy.position.set(p.x,p.y,z);dummy.rotation.set(0,0,(p.drill?0:p.rot||0)*Math.PI/180);dummy.scale.set(...scale,1);dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix);m.setColorAt(i,new THREE.Color('#ffffff'));}m.instanceMatrix.needsUpdate=true;padsGroup.add(m);pickables.push(m);instancedPads.push(m);}refreshInstanceColors();}
