function buildTraceHits(net){const groups=new Map();net.wires.forEach((w,i)=>{if(!groups.has(w.layer))groups.set(w.layer,{pos:[],ids:[]});const g=groups.get(w.layer),pts=arcPoints(w),z=w.layer===1?.09:w.layer===16?-1.34:-.22+(w.layer===2?0:w.layer===3?-.19:w.layer===14?-.38:-.57);for(let j=1;j<pts.length;j++){g.pos.push(...pts[j-1],z,...pts[j],z);g.ids.push(net.name+':'+i);}});for(const [layer,{pos,ids}]of groups){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));const material=new THREE.LineBasicMaterial({color:'#ffffff'});material.visible=false;const line=new THREE.LineSegments(geo,material);line.userData={net:net.name,segmentIds:ids,traceLayer:layer};traceGroup.add(line);pickables.push(line);}}
