function refreshMarkers(){if(!root)return;if(markerGroup){root.remove(markerGroup);markerGroup.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}markerGroup=new THREE.Group();root.add(markerGroup);notebook.data.points.forEach((point,i)=>{const p=board.pads.find(p=>p.id===point.id);if(!p)return;for(const z of [.19,-1.48]){const ring=mesh(new THREE.RingGeometry(.7,1.15,24),new THREE.MeshBasicMaterial({color:'#29c4ff',toneMapped:false,side:THREE.DoubleSide,depthTest:false}),markerGroup);ring.position.set(p.x,p.y,z);}textSprite(String(i+1),[p.x,p.y,.7],1.3,'#02354d',markerGroup);});}
function renderGenericBlocks(){let s='<svg viewBox="0 0 600 440" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Mapa de bloques funcionales"><rect width="600" height="440" fill="#f0f5f8"/><style>text{font:12px Arial;fill:#193b4b}</style>';s+=`<text x="22" y="30" style="font-size:18px">${board.domain||'Ardumoto'} · bloques funcionales</text><text x="22" y="53">Selecciona un bloque; comprueba cada unión en la lista de redes.</text>`;board.blocks.forEach((b,i)=>{const x=22+(i%2)*285,y=78+Math.floor(i/2)*112;s+=`<g data-block="${b.id}" style="cursor:pointer"><rect x="${x}" y="${y}" width="263" height="94" rx="10" fill="${b.color}33" stroke="${b.color}" stroke-width="2"/><text x="${x+12}" y="${y+26}" style="font-weight:bold">${b.title}</text><text x="${x+12}" y="${y+50}">${b.elements.slice(0,5).join(' · ')}</text><text x="${x+12}" y="${y+74}">${b.elements.length>5?'+'+(b.elements.length-5)+' componentes':'Explorar conexiones →'}</text></g>`;});s+='<text x="22" y="425">Mapa funcional; las conexiones eléctricas están en las redes del banco.</text></svg>';$('schematic').innerHTML=s;$('schematic').querySelectorAll('[data-block]').forEach(e=>e.onclick=()=>{activeBlock=e.dataset.block;showBlockSolution=true;renderBlocks();workstation?.selectBlock(activeBlock);$('blockPanel').scrollIntoView({behavior:'smooth',block:'start'});});}
function guideKey(){return 'circuitlab-method-v3-'+board.id;}
function setupProGuide(){guideIndex=0;$('inspectComponent').replaceChildren();const none=document.createElement('option');none.value='';none.textContent='Elegir componente…';$('inspectComponent').append(none);for(const el of board.elements){const o=document.createElement('option');o.value=el.name;o.textContent=el.name+' · '+(el.value||el.package);$('inspectComponent').append(o);}try{guideDone=JSON.parse(storage.getItem(guideKey())||'{}');}catch{guideDone={};}$('layerSelect').replaceChildren();const opts=[['surface','Caras exteriores'],...((board.layers||[{id:1,name:'Superior · Top'},{id:16,name:'Inferior · Bottom'}]).map(l=>[l.id,l.name]))];for(const [v,t]of opts){const o=document.createElement('option');o.value=v;o.textContent=t;$('layerSelect').append(o);}layerChoice='surface';$('layerSelect').value='surface';$('netSearch').value='';$('isolateNet').disabled=!state.net;$('openBlocks').textContent=board.blocks?'Identificar bloques de esta placa →':'Explorar una placa compleja por bloques →';renderMethod();}
function renderMethod(){const m=methodSteps[guideIndex];$('methodCount').textContent=`PASO ${guideIndex+1} / ${methodSteps.length}`;$('methodTitle').textContent=m.title;$('methodWhy').textContent=m.why;$('methodDo').textContent=m.do;$('methodProof').textContent=m.proof;$('methodDetail').textContent=m.detail;$('methodNote').value=guideDone[guideIndex]?.note||'';$('methodPrev').disabled=guideIndex===0;$('methodNext').disabled=guideIndex===7;$('methodDots').replaceChildren();methodSteps.forEach((x,i)=>{const b=document.createElement('button');b.textContent=i+1;b.title=x.title;b.className=(i===guideIndex?'active ':'')+(guideDone[i]?'done':'');b.onclick=()=>{saveMethodDraft();guideIndex=i;renderMethod();};$('methodDots').append(b);});$('methodStatus').textContent=board.fidelity||(board.educational?'Circuito original de entrenamiento con modelo eléctrico ideal.':'Placa basada en conexiones CAD originales. Cuerpos de componentes aproximados.');}
function saveMethodDraft(){const note=$('methodNote').value.trim();if(note){guideDone[guideIndex]={note,date:new Date().toISOString()};try{storage.setItem(guideKey(),JSON.stringify(guideDone));}catch{}}}
function prepareMethod(){const action=methodSteps[guideIndex].tool;if(action==='home'){homeView();setTool('inspect');}if(action==='blocks'){if(board.blocks){showBlockSolution=true;renderBlocks();$('blockPanel').scrollIntoView({behavior:'smooth',block:'start'});}else $('methodStatus').textContent='Usa una placa compleja para practicar bloques, o identifica entrada, componente y salida en este circuito.';}if(action==='reference'){const net=board.nets.find(n=>n.name==='GND')||board.nets.find(n=>/GND/.test(n.name));if(net){selectNet(net.name);markColor='#29c4ff';$('markColor').value=markColor;setTool('net');}}if(action==='route'){const route=board.guideRoute||board.nets.filter(n=>n.contacts.length>1&&n.wires.length).sort((a,b)=>a.contacts.length-b.contacts.length).slice(0,1).map(n=>n.contacts.slice(0,3)).flat();if(route?.length){const p=board.pads.find(p=>p.id===route[0]);if(p){selectNet(p.net);isolate=true;$('isolateNet').classList.add('active');refreshFaces();}setTool('point');$('methodStatus').textContent='Recorrido sugerido: '+route.join(' → ')+'. Añade hitos desde la lista de contactos.';}}if(action==='component'){setTool('inspect');$('methodStatus').textContent='Toca un cuerpo 3D o selecciona un componente en el panel de bloques; investiga los pads en la ficha de conexiones.';}if(action==='measure'){state.power=false;state.mode='continuity';setTool('measure');updateUI();$('methodStatus').textContent=board.exploreOnly?'En esta placa solo se comprueba conectividad CAD: misma red, no funcionamiento eléctrico.':'Coloca las puntas sobre los puntos que has predicho y elige el modo de medida apropiado.';}if(action==='record'){$('routeName').focus();$('methodStatus').textContent='Pon un nombre al recorrido y pulsa Guardar. Puedes descargar tus notas con el botón del cuaderno.';}}
function initProTools(){$('inspectComponent').onchange=e=>inspectPart(e.target.value);$('visualMode').onchange=e=>{visualMode=e.target.value;refreshFaces();};$('layerSelect').onchange=e=>{layerChoice=e.target.value;if(camera&&((layerChoice==='16'&&!viewBottom)||(layerChoice!=='16'&&layerChoice!=='surface'&&viewBottom)))flip();applyLayerView();};$('traceWidth').oninput=e=>{traceScale=Number(e.target.value);refreshFaces();};$('isolateNet').onclick=()=>{isolate=!isolate;$('isolateNet').classList.toggle('active',isolate);refreshFaces();};$('focusNet').onclick=()=>{if(!camera||!state.net)return;const ps=board.pads.filter(p=>p.net===state.net);if(!ps.length)return;const x=(Math.min(...ps.map(p=>p.x))+Math.max(...ps.map(p=>p.x)))/2+root.position.x,y=(Math.min(...ps.map(p=>p.y))+Math.max(...ps.map(p=>p.y)))/2+root.position.y,d=Math.max(20,Math.max(Math.max(...ps.map(p=>p.x))-Math.min(...ps.map(p=>p.x)),Math.max(...ps.map(p=>p.y))-Math.min(...ps.map(p=>p.y)))*1.7);controls.target.set(x,y,0);camera.position.set(x+d*.1,y-d*.45,(viewBottom?-1:1)*d);controls.update();};$('fullViewer').onclick=()=>{const el=document.querySelector('.viewer'),on=el.classList.toggle('expandedViewer');$('fullViewer').textContent=on?'⤢ Cerrar ampliación':'⛶ Ampliar banco';};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.viewer').classList.remove('expandedViewer');$('fullViewer').textContent='⛶ Ampliar banco';}});$('netSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#nets button').forEach(b=>{const n=board.nets.find(n=>n.name===b.dataset.net);b.hidden=!(n.name+' '+n.contacts.join(' ')).toLowerCase().includes(q);});};$('methodPrev').onclick=()=>{saveMethodDraft();guideIndex=Math.max(0,guideIndex-1);renderMethod();};$('methodNext').onclick=()=>{saveMethodDraft();guideIndex=Math.min(7,guideIndex+1);renderMethod();};$('methodComplete').onclick=()=>{if(!$('methodNote').value.trim()){$('methodStatus').textContent='Escribe lo que has identificado y cómo lo comprobarías antes de guardar el paso.';return;}saveMethodDraft();renderMethod();$('methodStatus').textContent='Razonamiento guardado para esta placa.';};$('methodApply').onclick=prepareMethod;$('methodNote').onchange=saveMethodDraft;for(const t of topicGuides){const d=document.createElement('details'),sum=document.createElement('summary'),p=document.createElement('p');sum.textContent=t.title;p.textContent=t.text;d.append(sum,p);$('topicGuides').append(d);}
 $('openBlocks').onclick=()=>{if(!board.blocks){freeMode();setBoard('computer');}$('blockPanel').scrollIntoView({behavior:'smooth',block:'start'});};}
